'use strict';

const toRegexRange = require('to-regex-range');

const RANGE_PATTERN = /^\s*(-?\d+)\s*-\s*(-?\d+)\s*$/;

/**
 * Convert a range string like "1-100" into a regex source string that
 * matches any integer in that range (inclusive).
 *
 * @param {string} range - e.g. "1-100", "-5-10", "-20--10"
 * @param {object} [options]
 * @param {boolean} [options.anchored=true] - wrap the pattern in ^...$
 * @returns {string}
 */
function rangeToRegexSource(range, { anchored = true } = {}) {
  const match = RANGE_PATTERN.exec(String(range));
  if (!match) {
    throw new Error(`Invalid range "${range}". Expected format: <min>-<max>, e.g. 1-100`);
  }

  let [min, max] = [Number(match[1]), Number(match[2])];
  if (!Number.isSafeInteger(min) || !Number.isSafeInteger(max)) {
    throw new Error(`Range bounds must be safe integers: "${range}"`);
  }
  if (min > max) [min, max] = [max, min];

  const source = toRegexRange(min, max, { capture: false, shorthand: true });
  return anchored ? `^(?:${source})$` : source;
}

/**
 * Same as rangeToRegexSource, but returns a RegExp object.
 */
function rangeToRegex(range, options) {
  return new RegExp(rangeToRegexSource(range, options));
}

module.exports = { rangeToRegex, rangeToRegexSource };
EOF
cat > src/cli.js <<'EOF'
#!/usr/bin/env node
'use strict';

const { rangeToRegexSource } = require('./range-to-regex');

const args = process.argv.slice(2);
const unanchored = args.includes('--unanchored');
const range = args.find((arg) => !arg.startsWith('--') || /^-\d/.test(arg));

if (!range || args.includes('--help') || args.includes('-h')) {
  console.error('Usage: range-to-regex <min>-<max> [--unanchored]');
  console.error('Example: range-to-regex 1-100');
  process.exit(range ? 0 : 1);
}

try {
  console.log(rangeToRegexSource(range, { anchored: !unanchored }));
} catch (err) {
  console.error(err.message);
  process.exit(1);
}
EOF
chmod +x src/cli.js
cat > test/range-to-regex.test.js <<'EOF'
'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { rangeToRegex, rangeToRegexSource } = require('../src/range-to-regex');

function assertExactRange(range, min, max, probeMin, probeMax) {
  const re = rangeToRegex(range);
  for (let n = probeMin; n <= probeMax; n++) {
    assert.equal(re.test(String(n)), n >= min && n <= max, `${range} vs ${n} (${re})`);
  }
}

test('1-100 matches exactly 1 through 100', () => {
  assertExactRange('1-100', 1, 100, -50, 1000);
});

test('handles single values and zero', () => {
  assertExactRange('0-0', 0, 0, -10, 10);
  assertExactRange('42-42', 42, 42, 0, 100);
});

test('handles negative ranges', () => {
  assertExactRange('-20-15', -20, 15, -100, 100);
  assertExactRange('-20--10', -20, -10, -100, 100);
});

test('swaps reversed bounds', () => {
  assertExactRange('100-1', 1, 100, 0, 200);
});

test('anchored pattern rejects partial matches', () => {
  const re = rangeToRegex('1-100');
  assert.equal(re.test('1000'), false);
  assert.equal(re.test('a5'), false);
  assert.equal(re.test('05'), false);
});

test('unanchored option returns the bare pattern', () => {
  assert.equal(rangeToRegexSource('1-9', { anchored: false }), '[1-9]');
});

test('rejects invalid input', () => {
  for (const bad of ['', '1', '1-', 'a-b', '1.5-3', '1-2-3']) {
    assert.throws(() => rangeToRegex(bad), /Invalid range/, bad);
  }
});
EOF
